code_example:
/* Storage Class: auto (Default) */
{
    int local_var = 10; // Automatic storage duration (stack)
    // Lifetime: Block scope only
}

/* Storage Class: static (Internal Linkage) */
static int global_data = 100; // File scope, static storage (data segment)

void func_a() {
    static int counter = 0; // Local scope, static storage
    counter++; // Retains value across calls
}

/* Storage Class: extern (External Linkage) */
// File 1 definition:
int shared_variable = 50;

// File 2 declaration:
extern int shared_variable; // Links to definition

/* Storage Class: register (Hint, often ignored) */
void fast_func(register int arg) {
    // Variable stored in CPU register (if available)
    // No address (cannot use '&')
    // register int* ptr; // Invalid in C++17/C23
}

/* Memory Model: Variable Storage Locations */
int global_uninitialized; // BSS (Zero initialized by loader)
int global_initialized = 1; // Data segment
const char* str_literal = "Const data"; // Read-Only Data (RODATA)
char buf[10]; // Stack or static, depending on scope

/* Memory Model: Heap Management */
int* dynamic_array = (int*)malloc(sizeof(int) * 10);
if (dynamic_array) {
    // Use memory
    free(dynamic_array);
}

/* Lifetime vs Scope */
void scope_example() {
    static int permanent_life = 0; // Static storage duration
    { // Inner scope
        int auto_life = 1; // Automatic storage duration
    } // auto_life destroyed
} // permanent_life persists
